public static int countNodes(BinNode<Integer> t) {
    if (t == null) {
        return 0;
    }
    return 1 + countNodes(t.getLeft()) + countNodes(t.getRight());
}

public static int sumTree(BinNode<Integer> t) {
    if (t == null) {
        return 0;
    }
    return t.getValue() + sumTree(t.getLeft()) + sumTree(t.getRight());
}

